<?php
 declare(strict_types=1); namespace Slim\Http; use Psr\Http\Message\UriInterface; class Uri implements UriInterface { protected $uri; public function __construct(UriInterface $uri) { $this->uri = $uri; } public function __set($name, $value) { } public function getAuthority(): string { return $this->uri->getAuthority(); } public function getFragment(): string { return $this->uri->getFragment(); } public function getHost(): string { return $this->uri->getHost(); } public function getPath(): string { return $this->uri->getPath(); } public function getPort(): ?int { return $this->uri->getPort(); } public function getQuery(): string { return $this->uri->getQuery(); } public function getScheme(): string { return $this->uri->getScheme(); } public function getUserInfo(): string { return $this->uri->getUserInfo(); } public function withFragment($fragment) { $uri = $this->uri->withFragment($fragment); return new static($uri); } public function withHost($host) { $uri = $this->uri->withHost($host); return new static($uri); } public function withPath($path) { $uri = $this->uri->withPath($path); return new static($uri); } public function withPort($port) { $uri = $this->uri->withPort($port); return new static($uri); } public function withQuery($query) { $uri = $this->uri->withQuery($query); return new static($uri); } public function withScheme($scheme) { $uri = $this->uri->withScheme($scheme); return new static($uri); } public function withUserInfo($user, $password = null) { $uri = $this->uri->withUserInfo($user, $password); return new static($uri); } public function __toString(): string { return $this->uri->__toString(); } public function getBaseUrl(): string { $scheme = $this->uri->getScheme(); $authority = $this->uri->getAuthority(); return ($scheme !== '' ? $scheme . ':' : '') . ($authority !== '' ? '//' . $authority : ''); } } 